const std = @import("std");

pub fn enabled(value: bool) bool {
    return value == true;
}

test "keeps enabled" {
    if (!enabled(true)) {
        std.debug.print("CASE root.keeps enabled\n", .{});
        std.debug.print("FAIL src/root.zig:12\n", .{});
    }
    try std.testing.expect(enabled(true));
}
